// Real in-game icon URLs (docs/10 D-059): ability spell art and shop item art
// generated by scripts/generate-game-icons.mjs. Consumers fall back to the
// generated pixel icons when a def has no real art (class filler abilities,
// unmatchable nostalgia items).
import { ABILITY_ICONS, ITEM_ICONS } from "./icon-manifest.generated";

/** Real spell-art URL for an authored kit ability ({id}-q / {id}-r), or "". */
export function abilityArtURL(def: { id: string; behavior: string }): string {
  const match = def.id.match(/^(.+)-([qr])$/);
  if (!match) return "";
  const [, championId, slot] = match;
  return ABILITY_ICONS[championId]?.[slot as "q" | "r"] ? `art/ability/${def.id}.webp` : "";
}

/** Real shop-item art URL, or "" when the item has no matched game icon. */
export function itemArtURL(itemId: string): string {
  return ITEM_ICONS[itemId] ? `art/item/${itemId}.webp` : "";
}
